(13165,2638,'C','à polêmica entre o reconhecimento dos valores inovadores e a presença de outros, consagrados, que garantem a vida em sociedade.',1,NULL,'2026-03-09 04:51:33','2026-03-09 04:51:33'),
(13166,2638,'D','ao caráter contraditório da atitude daqueles que se limitam a conhecimentos fundamentados em valores consagrados.',0,NULL,'2026-03-09 04:51:33','2026-03-09 04:51:33'),
(13167,2638,'E','ao conflito originado pela supremacia dos princípios teóricos, de um lado, e pela crença nos fenômenos práticos, de outro.',0,NULL,'2026-03-09 04:51:33','2026-03-09 04:51:33'),
(13168,2639,'A','as certezas oferecem segurança e tranquilidade para a vida em sociedade.',1,NULL,'2026-03-09 04:51:33','2026-03-09 04:51:33'),
