(17705,3554,'C','Lesão de ramo aberrante da artéria obturadora, também conhecida como “coroa mortis”, que cruza lateralmente ao ligamento de Cooper.',1,NULL,'2026-03-09 04:52:10','2026-03-09 04:52:10'),
(17706,3554,'D','Lesão da artéria pudenda externa, ramo da femoral, que acompanha os vasos espermáticos pelo anel inguinal profundo.',0,NULL,'2026-03-09 04:52:10','2026-03-09 04:52:10'),
(17707,3554,'E','Lesão de ramo da artéria vesical inferior, que emerge do plexo venoso retropúbico e cruza anteriormente ao espaço de Retzius.',0,NULL,'2026-03-09 04:52:10','2026-03-09 04:52:10'),
(17708,3555,'A','esplênica proximal (tronco esplênico).',0,NULL,'2026-03-09 04:52:10','2026-03-09 04:52:10'),
(17709,3555,'B','gastroepiploica direita.',0,NULL,'2026-03-09 04:52:10','2026-03-09 04:52:10'),
(17710,3555,'C','gástrica esquerda (coronária gástrica).',0,NULL,'2026-03-09 04:52:10','2026-03-09 04:52:10'),
