(18099,3633,'B','realizar a investigação após suspensão da anticoagulação oral, uma vez que esta interfere na avaliação da dosagem das proteínas C e S.',1,NULL,'2026-03-09 04:52:11','2026-03-09 04:52:11'),
(18100,3633,'C','solicitar pesquisa de anticoagulante lúpico nesse momento, uma vez que ele não sofre interferência da anticoagulação.',0,NULL,'2026-03-09 04:52:11','2026-03-09 04:52:11'),
(18101,3633,'D','iniciar investigação para trombofilias após o segundo evento trombótico, devido ao baixo risco de recorrência nessa paciente.',0,NULL,'2026-03-09 04:52:11','2026-03-09 04:52:11'),
(18102,3633,'E','solicitar dosagem de homocisteína plasmática, pois é o fator de risco mais associado à trombose em jovens.',0,NULL,'2026-03-09 04:52:11','2026-03-09 04:52:11'),
