(18166,3646,'D','Choque cardiogênico por infarto perioperatório, sem elevação de PVC.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18167,3646,'E','Disfunção ventricular direita por sobrecarga de pós-carga (embolia pulmonar maciça).',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
