(18191,3651,'D','lipoma do cordão espermático.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18192,3651,'E','linfadenopatia inguinal.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
