(18195,3652,'C','Ducto hepático comum, porção superior do ligamento hepatoduodenal e artéria hepática direita.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18196,3652,'D','Ducto cístico, artéria cística e margem inferior do fígado.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
