(18202,3653,'E','acessório (XI par).',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18203,3654,'A','Lesão da artéria epigástrica inferior, que cruza o trato iliopúbico medialmente ao anel femoral.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18204,3654,'B','Lesão da artéria circunflexa ilíaca profunda, que passa posteriormente ao trato iliopúbico e irriga o músculo transverso do abdome.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18205,3654,'C','Lesão de ramo aberrante da artéria obturadora, também conhecida como “coroa mortis”, que cruza lateralmente ao ligamento de Cooper.',1,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18206,3654,'D','Lesão da artéria pudenda externa, ramo da femoral, que acompanha os vasos espermáticos pelo anel inguinal profundo.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18207,3654,'E','Lesão de ramo da artéria vesical inferior, que emerge do plexo venoso retropúbico e cruza anteriormente ao espaço de Retzius.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18208,3655,'A','esplênica proximal (tronco esplênico).',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18209,3655,'B','gastroepiploica direita.',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
(18210,3655,'C','gástrica esquerda (coronária gástrica).',0,NULL,'2026-03-09 04:52:12','2026-03-09 04:52:12'),
