(18746,3762,'D','Lesão da artéria pudenda externa, ramo da femoral, que acompanha os vasos espermáticos pelo anel inguinal profundo.',0,NULL,'2026-03-09 04:52:14','2026-03-09 04:52:14'),
(18747,3762,'E','Lesão de ramo da artéria vesical inferior, que emerge do plexo venoso retropúbico e cruza anteriormente ao espaço de Retzius.',0,NULL,'2026-03-09 04:52:14','2026-03-09 04:52:14'),
(18748,3763,'A','esplênica proximal (tronco esplênico).',0,NULL,'2026-03-09 04:52:14','2026-03-09 04:52:14'),
