(19140,3841,'C','solicitar pesquisa de anticoagulante lúpico nesse momento, uma vez que ele não sofre interferência da anticoagulação.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19141,3841,'D','iniciar investigação para trombofilias após o segundo evento trombótico, devido ao baixo risco de recorrência nessa paciente.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19142,3841,'E','solicitar dosagem de homocisteína plasmática, pois é o fator de risco mais associado à trombose em jovens.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
