(19231,3859,'D','lipoma do cordão espermático.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19232,3859,'E','linfadenopatia inguinal.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
