(19242,3861,'E','acessório (XI par).',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19243,3862,'A','Lesão da artéria epigástrica inferior, que cruza o trato iliopúbico medialmente ao anel femoral.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19244,3862,'B','Lesão da artéria circunflexa ilíaca profunda, que passa posteriormente ao trato iliopúbico e irriga o músculo transverso do abdome.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19245,3862,'C','Lesão de ramo aberrante da artéria obturadora, também conhecida como “coroa mortis”, que cruza lateralmente ao ligamento de Cooper.',1,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
