(19247,3862,'E','Lesão de ramo da artéria vesical inferior, que emerge do plexo venoso retropúbico e cruza anteriormente ao espaço de Retzius.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19248,3863,'A','esplênica proximal (tronco esplênico).',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19249,3863,'B','gastroepiploica direita.',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
(19250,3863,'C','gástrica esquerda (coronária gástrica).',0,NULL,'2026-03-09 04:52:16','2026-03-09 04:52:16'),
