(23213,4673,'B','moralidade.',0,NULL,'2026-03-09 04:52:35','2026-03-09 04:52:35'),
(23214,4673,'C','impessoalidade.',1,NULL,'2026-03-09 04:52:35','2026-03-09 04:52:35'),
