(23243,4679,'B','condição incompreensível ou contraditória.',0,NULL,'2026-03-09 04:52:35','2026-03-09 04:52:35'),
(23244,4679,'C','encargo ilícito ou impossível, se constituir o motivo determinante da liberalidade.',0,NULL,'2026-03-09 04:52:35','2026-03-09 04:52:35'),
(23245,4679,'D','condição ilícita que privar de todo efeito o negócio jurídico.',0,NULL,'2026-03-09 04:52:35','2026-03-09 04:52:35'),
(23246,4679,'E','condição ilícita que sujeita o negócio jurídico ao puro arbítrio de uma das partes.',0,NULL,'2026-03-09 04:52:35','2026-03-09 04:52:35'),
